{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C129","C130","C150","C162","C167","C246","C264","C236","C269","C227","C61","C49","C46"],
  "contradictory_card_ids": ["C191","C200","C211","C219","C194"],
  "prediction_basis_card_ids": ["C129","C130","C246","C264","C269","C227","C61","C49","C46"],
  "claims": [
    {
      "claim": "L4 records for sulfonylurea analogs show high intestinal absorption: glipizide FA >95% (C129), glimepiride almost completely absorbed (C130), and high Caco-2 Papp for glipizide (~10×10^-6 cm/s; C150, C162) and glibenclamide (18.1×10^-6 cm/s; C167), supporting that the query's acidic sulfonyl semicarbazide can be absorbed despite ionization.",
      "card_ids": ["C129","C130","C150","C162","C167"]
    },
    {
      "claim": "L6 hepatic clearance records show tolbutamide, a sulfonylurea analog, has low intrinsic clearance in human liver microsomes (wild-type CYP2C9 CLint 2.71×10^-4 µL/mg/min, C246; mean HLM Vmax/Km 3.14 µL/min/mg, C264/C236; scaled CLint 2.00 ml/min/kg, C269; pooled HLM 1.87 µL/min/mg, C227), indicating low hepatic first-pass loss for this chemotype and supporting F>=20.",
      "card_ids": ["C246","C264","C236","C269","C227"]
    },
    {
      "claim": "L5 records show glibenclamide is a P-gp/BCRP substrate (C191, C200, C211, C219) and tolbutamide undergoes intestinal CYP2C9 metabolism (C194), providing possible presystemic-loss context, but none establishes F<20 and they are outweighed by absorption and low hepatic clearance evidence.",
      "card_ids": ["C191","C200","C211","C219","C194"]
    },
    {
      "claim": "Prior human absolute-bioavailability contexts (zolpidem ~68-70%, C61; solifenacin 88%, C49; quinapril ~50%, C46) support that small oral drugs with ionizable groups can achieve F>=20, though transferability is structural rather than direct.",
      "card_ids": ["C61","C49","C46"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C246","C264","C236","C269","C227"]
    }
  ],
  "evidence_gaps": [
    "No direct measured absolute oral bioavailability for the query molecule.",
    "No query-specific permeability, efflux, intestinal metabolism, or hepatic clearance data.",
    "L4/L5/L6 records are for sulfonylurea analogs (glipizide, glimepiride, glibenclamide, tolbutamide, acetohexamide, celecoxib), not the query; the semicarbazide and bicyclic amine may alter absorption and metabolism.",
    "The query's zwitterionic character (neutral fraction 0.03, logD 0.1) remains a physicochemical concern, not endpoint proof.",
    "No human PK, dose, formulation, or route data for the query."
  ],
  "decision_summary": "L6 hepatic clearance records for tolbutamide show low intrinsic clearance, supporting low first-pass loss for the sulfonylurea-like core and strengthening the high prediction; combined with L4 high absorption evidence for sulfonylurea analogs and absence of affirmative F<20 evidence, F>=20 remains better supported, though query-specific data are lacking."
}

